defmodule Exosphere.ATProto.Spaces.SpaceMetaTest do
  @moduledoc false
  use ExUnit.Case, async: true

  alias Exosphere.ATProto.CBOR, as: DagCbor
  alias Exosphere.ATProto.Star
  alias Exosphere.ATProto.Spaces.SpaceMeta
  alias Exosphere.Test.Interop

  # Generated by the reference (`serializeSpaceMeta` at atproto 98ef3a6).
  @corpus Interop.spaces_corpus("space-meta.json")

  defp unhex(s), do: Base.decode16!(s, case: :mixed)

  defp corpus_archive do
    a = @corpus["archive"]

    %{
      space: a["space"],
      policy: a["policy"],
      policy_state: Enum.map(a["policyState"], &{&1["key"], &1["value"]}),
      writers:
        Enum.map(a["writers"], fn w ->
          %{did: w["did"], rev: w["rev"], data: unhex(w["data"]), space_rev: w["spaceRev"]}
        end)
    }
  end

  test "decodes the reference archive" do
    assert {:ok, archive} = SpaceMeta.decode(Base.decode64!(@corpus["star"]))
    assert archive == corpus_archive()
  end

  test "encodes the reference archive byte-for-byte, whatever the input order" do
    archive = corpus_archive()

    shuffled = %{
      archive
      | policy_state: Enum.reverse(archive.policy_state),
        writers: Enum.reverse(archive.writers)
    }

    assert SpaceMeta.encode(shuffled) == Base.decode64!(@corpus["star"])
  end

  describe "rejects" do
    setup do
      meta = %{
        "$type" => "atproto-space-meta",
        "ver" => 1,
        "space" => @corpus["archive"]["space"]
      }

      policy = {"policy", DagCbor.encode!(%{"$type" => "com.atproto.personalspace.policy"})}

      writer =
        {"writer/did:plc:bob",
         DagCbor.encode!(%{
           "rev" => "3kbcq3p7ad2k4",
           "data" => %CBOR.Tag{tag: :bytes, value: <<0::256>>},
           "spaceRev" => "3kbcq3p7ad3a2"
         })}

      member = {"com.atproto.memberspace.member/did:plc:a", DagCbor.encode!(%{"read" => true})}
      %{meta: meta, policy: policy, writer: writer, member: member}
    end

    test "a missing policy", ctx do
      assert {:error, :missing_policy} = SpaceMeta.decode(Star.encode(ctx.meta, [ctx.writer]))
    end

    test "a section out of place", ctx do
      assert {:error, :section_out_of_order} =
               SpaceMeta.decode(Star.encode(ctx.meta, [ctx.policy, ctx.writer, ctx.member]))
    end

    test "a duplicate key", ctx do
      assert {:error, {:duplicate_or_out_of_order_key, _}} =
               SpaceMeta.decode(Star.encode(ctx.meta, [ctx.policy, ctx.member, ctx.member]))
    end

    test "a malformed writer or a non-map value", ctx do
      bad = {"writer/not-a-did", elem(ctx.writer, 1)}

      assert {:error, {:invalid_writer, _}} =
               SpaceMeta.decode(Star.encode(ctx.meta, [ctx.policy, bad]))

      assert {:error, :value_not_a_map} =
               SpaceMeta.decode(Star.encode(ctx.meta, [{"policy", DagCbor.encode!([1])}]))
    end

    test "the wrong profile or version", ctx do
      assert {:error, :wrong_star_type} =
               SpaceMeta.decode(Star.encode(%{ctx.meta | "$type" => "atproto-space-repo"}, []))

      assert {:error, :invalid_space_meta} =
               SpaceMeta.decode(Star.encode(%{ctx.meta | "ver" => 2}, [ctx.policy]))
    end
  end
end
